\begin{exercise}
\label{prob:7-9}


7-9. Show that the formula

\[
A \cdot  \left\lbrack  x\right\rbrack   = \left\lbrack  {Ax}\right\rbrack
\]

defines a smooth, transitive left action of $\mathrm{{GL}}\left( {n + 1,\mathbb{R}}\right)$ on ${\mathbb{{RP}}}^{n}$ .
\end{exercise}

